body.onloadscript:



if (userType == "S") {
    filterObj.filterPull.filter.items.F_USER_COMPANY.activeItem.parentNode.parentNode.parentNode.parentNode.hidden = true;
}

var cntrType = Sepoa.request["cntrType"];

/*
	cntrType 메뉴클릭시 alias 로 진입한다.
	최초 1개 게시판으로 운용되었으나, 계약용을 추가로 분리해달라는 요청을 받음.
	alias C를 달아서 분리하였으나 목적과 다르게 반대로 사용하며 데이터가 적재된상태이고
	수정이 불가능하여 명칭과 반대로 서비스를 사용중

	QnA_MANAGER = 법무검토관리자 → 계약서 법무검토 요청현황
	QnA_MANAGER_D = 법무검토관리자(일반) → 일반 법무검토 요청현황

	cntrType = undefined 	(법무검토>계약서 법무검토 요청현황)
	cntrType = "C"			(법무검토>일반 법무검토 요청현황)
*/

// ST: 담당자 팝업지정(SELECT_MANAGER) 미사용 → 항상 숨김
gridObj.setColumnHidden(gridObj.getColIndexById('SELECT_MANAGER'), 1);

if (cntrType == "C") {
    dataOutput.setValue("CNTR_TYPE", cntrType);
}
// ST: 완료여부(CHECK_FLAG)는 법무팀장(QnA_MASTER)만 표시/수정
if (!Sepoa.info.CTRL_CODE.split(",").includes("QnA_MASTER")) {
    gridObj.setColumnHidden(gridObj.getColIndexById('CHECK_FLAG'), 1);
}




    if (id == 'filter' || id == 'search') {
        doQuery();
    }






    resizeGrid();

userscript.function:

var cntrType = Sepoa.request["cntrType"];
var headerText = "";

if (cntrType == "C") {
    headerText = Sepoa.cache.text.get("QA_002.LAYOUT_A_HEADER_C");
} else {
    headerText = Sepoa.cache.text.get("QA_002.LAYOUT_A_HEADER");
}

callFunction(['p'], "setHeaderText", [headerText]);

btnObj.showButton('QA_LINK_BUTTON', false);
btnObj.showButton('QA_START_REVIEW', isLegalManagerForMenu());
btnObj.showButton('QA_RECALL_REVIEW', isLegalManagerForMenu());

// 팝업 제어
if (isPopup()) {
    btnObj.showButton('SEARCH', false);
    btnObj.showButton('QA_WRITE', false);
    btnObj.showButton('QA_START_REVIEW', false);
    btnObj.showButton('QA_RECALL_REVIEW', false);
    btnObj.showButton('QA_LINK_BUTTON', true);

    // TODO : 수정내용
    filterObj.setHide("F_KEYWORD");
    filterObj.setHide("F_ADD_USER");
    gridObj.setColumnHidden(gridObj.getColIndexById("SELECT_MANAGER"), true);
}

// 저장된 필터 값 복원
restoreFilterValues();

doQuery();


var ctrlArr = Sepoa.info.CTRL_CODE.split(",");
var cntrType = Sepoa.request["cntrType"];
// 일반(C): QnA_MANAGER_D / 계약서: QnA_MANAGER
if (cntrType == "C") {
    return ctrlArr.indexOf("QnA_MANAGER_D") >= 0;
}
return ctrlArr.indexOf("QnA_MANAGER") >= 0;


switch (name) {
    case "SEARCH":
        doQuery();
        break;
    case "QA_WRITE":
        callFunction('QA_002', 'changeFrame', ['write']);
        break;
    case "QA_START_REVIEW":
        doStartReview();
        break;
    case "QA_RECALL_REVIEW":
        doRecallReview();
        break;
    case "QA_LINK_BUTTON":
        doSelectRefDoc();
        break;
    case "QA_EXCEL_DOWNLOAD":
        doExcelDownload();
        break;
    default:
        break;
}


var msg = obj.getUserData("", "message");
var status = obj.getUserData("", "status");

var rowCount = gridObj.getRowsNum();
if (rowCount == 0) {
    Alert("조회결과가 없습니다");
    return false;
}

if (rowCount > 0) {
    var colSeqIndex = gridObj.getColIndexById('ROW_NUM');
    if (colSeqIndex == null || colSeqIndex < 0) {
        return;
    }
    var seqCount = rowCount;

    for (var i = 0; i < rowCount; i++) {
        var rowID = gridObj.getRowId(i);

        gridObj.cells(rowID, colSeqIndex).setValue(seqCount--);
    }
}


var header = gridObj.getColumnId(cInd);
var qnaNumber = gridObj.gridGetCellValueId(rId, 'QNA_NUMBER');
var checkFlag = gridObj.gridGetCellValueId(rId, 'CHECK_FLAG');
var qnaStatus = gridObj.gridGetCellValueId(rId, 'STATUS');

let ctrlArr = Sepoa.info.CTRL_CODE.split(",");
let ctrlFlag = ctrlArr.indexOf("QnA_MANAGER") >= 0 || ctrlArr.indexOf("QnA_MANAGER_D") >= 0;

let profileFlag = (Sepoa.info.MENU_PROFILE_CODE == 'MUP2011020001') ? true : false;

if (header == 'SUBJECT') {
    if (checkFlag != 'Y' || ctrlFlag || profileFlag) {
        callFunction('QA_002', 'changeFrame', ['view', qnaNumber]);
    } else if (checkFlag == 'Y' && (!ctrlFlag || !profileFlag)) {
        callFunction('QA_002', 'changeFrame', ['view', qnaNumber, checkFlag]);
    }
} else if (header == "SELECTED") {
    let selectedFlag = gridObj.cells(rId, gridObj.getColIndexById("SELECTED")).getValue();
    if (selectedFlag == 0) {
        gridObj.cells(rId, gridObj.getColIndexById("SELECTED")).setValue('1');
    } else {
        gridObj.cells(rId, gridObj.getColIndexById("SELECTED")).setValue('0');
    }
}

// 팝업일 경우 row를 선택해도 체크가 되도록 설정
if (isPopup() && header != "SELECTED") {
    let selectedFlag = gridObj.cells(rId, gridObj.getColIndexById("SELECTED")).getValue();

    if (selectedFlag == 0) {
        gridObj.cells(rId, gridObj.getColIndexById("SELECTED")).setValue('1');
    } else {
        gridObj.cells(rId, gridObj.getColIndexById("SELECTED")).setValue('0');
    }
}


if (!isLegalManagerForMenu()) {
    Alert("법무검토 담당자만 검토진행할 수 있습니다.");
    return;
}

var selectedRows = gridObj.getGridChangedRows("SELECTED");
if (!selectedRows || selectedRows.length <= 0) {
    Alert("검토진행할 항목을 선택해주세요.");
    return;
}

var qnaNumbers = [];
var sessionName = Sepoa.info.NAME_LOC || Sepoa.info.NAME || "";

for (var i = 0; i < selectedRows.length; i++) {
    var rId = selectedRows[i];
    var qnaNumber = gridObj.gridGetCellValueId(rId, 'QNA_NUMBER');
    var qnaStatus = gridObj.gridGetCellValueId(rId, 'STATUS');
    var managerName = gridObj.gridGetCellValueId(rId, 'MANAGER');

    if (!qnaNumber) {
        continue;
    }

    // 그리드 MANAGER는 이름만 있으므로, 본인 담당 여부는 이름 비교(보조) + 서버 최종검증
    if (qnaStatus == "G" && managerName && sessionName && managerName == sessionName) {
        Alert("검토진행중인 건으로 선택할 수 없습니다.<br/>[" + qnaNumber + "]");
        return;
    }

    if (qnaStatus == "G") {
        Alert("이미 검토진행중인 건입니다.<br/>[" + qnaNumber + "]");
        return;
    }

    if (qnaStatus != "F") {
        Alert("검토대기 건에 대해서만 검토진행할 수 있습니다.<br/>[" + qnaNumber + "]");
        return;
    }

    qnaNumbers.push(qnaNumber);
}

if (qnaNumbers.length <= 0) {
    Alert("검토진행할 항목을 선택해주세요.");
    return;
}

var cntrType = Sepoa.request["cntrType"] || "";
if (cntrType === "undefined") {
    cntrType = "";
}
var params = {
    SELECTED_QNA_NUMBERS: qnaNumbers.join(','),
    CNTR_TYPE: cntrType
};

doServiceAjax('sepoa.svc.board.SepoaQAService', 'TRANSACTION', 'doStartReview', params, function(so) {
    if (so.status == 1) {
        Alert("검토진행 처리되었습니다.");
        doQuery();
    } else {
        Alert(so.message || "검토진행 처리에 실패하였습니다.");
    }
});


if (!isLegalManagerForMenu()) {
    Alert("법무검토 담당자만 회수할 수 있습니다.");
    return;
}

var selectedRows = gridObj.getGridChangedRows("SELECTED");
if (!selectedRows || selectedRows.length <= 0) {
    Alert("회수할 항목을 선택해주세요.");
    return;
}

var qnaNumbers = [];
var sessionName = Sepoa.info.NAME_LOC || Sepoa.info.NAME || "";
var sessionId = Sepoa.info.ID || "";

for (var i = 0; i < selectedRows.length; i++) {
    var rId = selectedRows[i];
    var qnaNumber = gridObj.gridGetCellValueId(rId, 'QNA_NUMBER');
    var qnaStatus = gridObj.gridGetCellValueId(rId, 'STATUS');
    var checkFlag = gridObj.gridGetCellValueId(rId, 'CHECK_FLAG') || 'N';
    var managerName = gridObj.gridGetCellValueId(rId, 'MANAGER');
    var managerId = '';
    try {
        managerId = gridObj.gridGetCellValueId(rId, 'MANAGER_ID') || '';
    } catch (e) {
        managerId = '';
    }

    if (!qnaNumber) {
        continue;
    }

    if (qnaStatus != "L" && qnaStatus != "A") {
        Alert("이견없음 또는 검토요청 건만 회수할 수 있습니다.<br/>[" + qnaNumber + "]");
        return;
    }

    if (checkFlag == "Y") {
        Alert("팀장이 완료여부(Y)를 지정한 건은 회수할 수 없습니다.<br/>[" + qnaNumber + "]");
        return;
    }

    // 본인 담당: MANAGER_ID 우선, 없으면 이름 비교(보조) — 최종은 서버 검증
    var isMyCase = false;
    if (managerId && sessionId && managerId == sessionId) {
        isMyCase = true;
    } else if (managerName && sessionName && managerName == sessionName) {
        isMyCase = true;
    }
    if (!isMyCase) {
        Alert("본인이 담당한 건만 회수할 수 있습니다.<br/>[" + qnaNumber + "]");
        return;
    }

    qnaNumbers.push(qnaNumber);
}

if (qnaNumbers.length <= 0) {
    Alert("회수할 항목을 선택해주세요.");
    return;
}

Confirm("선택한 건을 검토진행중으로 회수하시겠습니까?<br/>이견없음/검토요청 선택을 다시 할 수 있습니다.", function(result) {
    if (!result) {
        return;
    }

    var cntrType = Sepoa.request["cntrType"] || "";
    if (cntrType === "undefined") {
        cntrType = "";
    }
    var params = {
        SELECTED_QNA_NUMBERS: qnaNumbers.join(','),
        CNTR_TYPE: cntrType
    };

    doServiceAjax('sepoa.svc.board.SepoaQAService', 'TRANSACTION', 'doRecallReview', params, function(so) {
        if (so.status == 1) {
            Alert("회수 처리되었습니다. 상태가 검토진행중으로 변경되었습니다.");
            doQuery();
        } else {
            Alert(so.message || "회수 처리에 실패하였습니다.");
        }
    });
});


var header = gridObj.getColumnId(cInd);
let ctrlArr = Sepoa.info.CTRL_CODE.split(",");
let isMaster = (ctrlArr.indexOf("QnA_MASTER") >= 0);
let qnaStatus = gridObj.gridGetCellValueId(rId, 'STATUS');

// ST: 이견없음(L)/검토요청(A) 이후에만, QnA_MASTER만 CHECK_FLAG 수정 (Y 확정 후 되돌리기 불가)
if (header === "CHECK_FLAG" && stage == 0) {
    if (!isMaster) {
        Alert("법무팀장만 완료여부를 지정할 수 있습니다.");
        return false;
    }
    if (!["L", "A"].includes(qnaStatus)) {
        Alert("이견없음 또는 검토요청 건에 대해서만<br/>완료여부를 지정할 수 있습니다.");
        return false;
    }
    var curCheck = gridObj.gridGetCellValueId(rId, 'CHECK_FLAG') || 'N';
    if (curCheck === 'Y') {
        Alert("완료여부(Y)는 변경할 수 없습니다.");
        return false;
    }
}

if (isMaster && stage == 2 && header === "CHECK_FLAG" && (oValue != nValue)) {
    if (oValue === 'Y') {
        Alert("완료여부(Y)는 변경할 수 없습니다.");
        gridObj.cells(rId, gridObj.getColIndexById(header)).setValue(oValue);
        return false;
    }
    if (nValue !== 'Y') {
        Alert("완료여부는 Y로만 지정할 수 있습니다.");
        gridObj.cells(rId, gridObj.getColIndexById(header)).setValue(oValue);
        return false;
    }
    var rowData = gridObj._getRowData(rId);
    rowData.CHECK_FLAG = nValue;
    doServiceAjax('sepoa.svc.board.SepoaQAService', 'TRANSACTION', 'doCheckFlagUpdate', rowData, function(so) {
        if (so.status == 1) {
            gridObj.cells(rId, gridObj.getColIndexById(header)).setValue(nValue);
            // Y 지정 시 상태를 검토완료(CC)로 반영
            var statusCol = gridObj.getColIndexById('STATUS');
            if (statusCol >= 0) {
                gridObj.cells(rId, statusCol).setValue('CC');
            }
        } else {
            Alert(so.message || so.meesage || "완료여부 변경에 실패하였습니다.");
            gridObj.cells(rId, gridObj.getColIndexById(header)).setValue(oValue);
            return;
        }
    });
} else if (header == "SELECTED") {
    return true;
}


if (isPopup()) {
    const checkedRows = gridObj.getSelectedRows("SELECTED"); // 배열 반환

    if (checkedRows.length <= 0) {
        Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0005')); // 선택된 행이 없습니다.
        return;
    }

    // 주소와 제목을 담을 객체
    let callbackObj = {};
    // 체크 된 모든 글 정보를 담을 배열
    let callbackParams = [];

    // 배열 돌면서 qna넘버 가져온다.
    for (const rId of checkedRows) {
        let qnaNumber = gridObj.gridGetCellValueId(rId, 'QNA_NUMBER');
        let subject = gridObj.cells(rId, gridObj.getColIndexById("SUBJECT")).getValue();

        let url = document.location.origin + '/link.sux?ln=79bde217-722b-4144-97f9-1ac7f7d36979&QNA_NUMBER=' + qnaNumber;

        callbackObj.addr = url;
        callbackObj.subject = subject;

        callbackParams.push(Object.assign({}, callbackObj));
    }

    Sepoa.params.callback(callbackParams);

    selfObj.close();
}


try {
    // filterObj.getFilterData()로 전체 필터 데이터 가져오기
    var filterData = filterObj.getFilterData();

    // sessionStorage에 저장
    // cntrType이 null, undefined, 빈 문자열인 경우 'default'로 처리
    var cntrType = Sepoa.request["cntrType"];
    var storageKey = 'QA_002_FILTER_' + (cntrType && cntrType !== 'undefined' ? cntrType : 'default');
    sessionStorage.setItem(storageKey, JSON.stringify(filterData));
} catch (e) {
    // 에러 발생 시 무시 (필터 저장 실패해도 상세 화면 이동은 진행)
}


try {
    // cntrType이 null, undefined, 빈 문자열인 경우 'default'로 처리
    var cntrType = Sepoa.request["cntrType"];
    var storageKey = 'QA_002_FILTER_' + (cntrType && cntrType !== 'undefined' ? cntrType : 'default');
    var savedFilterData = sessionStorage.getItem(storageKey);

    if (!savedFilterData) {
        return; // 저장된 필터 값이 없으면 복원하지 않음
    }

    var filterData = JSON.parse(savedFilterData);

    // 각 필터 항목별로 값 복원
    // 조회기간 (F_WRITE_DATE_FROM, F_WRITE_DATE_TO)
    if (filterData.F_WRITE_DATE_FROM && filterData.F_WRITE_DATE_TO) {
        try {
            var calendarItem = filterObj.getItemById('F_WRITE_DATE');
            if (calendarItem) {
                // YYYYMMDD 형식을 Date 객체로 변환
                var fromDateStr = filterData.F_WRITE_DATE_FROM;
                var toDateStr = filterData.F_WRITE_DATE_TO;

                // 날짜 문자열을 Date 객체로 변환 (YYYYMMDD 형식)
                var fromDate = new Date(
                    fromDateStr.substring(0, 4),
                    parseInt(fromDateStr.substring(4, 6)) - 1,
                    fromDateStr.substring(6, 8)
                );
                var toDate = new Date(
                    toDateStr.substring(0, 4),
                    parseInt(toDateStr.substring(4, 6)) - 1,
                    toDateStr.substring(6, 8)
                );

                // filter_v2 형식인 경우 _setInputDate 메서드 사용
                if (calendarItem._setInputDate) {
                    calendarItem._setInputDate("from", fromDate);
                    calendarItem._setInputDate("to", toDate);
                }
                // fromObj와 toObj가 있는 경우에도 설정
                else if (calendarItem.fromObj && calendarItem.toObj) {
                    calendarItem.fromObj.setDate(fromDate);
                    calendarItem.toObj.setDate(toDate);
                }
            }
        } catch (e) {
            // calendar 복원 실패 시 무시
            console.log("Calendar filter restore error:", e);
        }
    }

    // 검색어 (KEYWORD)
    if (filterData.KEYWORD) {
        filterObj.setValue('KEYWORD', filterData.KEYWORD);
    }

    // 필터 옵션들 (F_KEYWORD, F_ADD_USER, F_MANAGER, F_DEPT)
    if (filterData.F_KEYWORD) {
        filterObj.setValue('F_KEYWORD', filterData.F_KEYWORD);
    }
    if (filterData.F_ADD_USER) {
        filterObj.setValue('F_ADD_USER', filterData.F_ADD_USER);
    }
    if (filterData.F_MANAGER) {
        filterObj.setValue('F_MANAGER', filterData.F_MANAGER);
    }
    if (filterData.F_DEPT) {
        filterObj.setValue('F_DEPT', filterData.F_DEPT);
    }

    // 상태 (F_STATUS)
    if (filterData.F_STATUS) {
        filterObj.setValue('F_STATUS', filterData.F_STATUS);
    }
} catch (e) {
    // 에러 발생 시 무시 (필터 복원 실패해도 정상 진행)
}


// 선택한 행이 있는지 확인
var selectedRows = gridObj.getGridChangedRows("SELECTED");
var qnaNumbers = [];

if (selectedRows && selectedRows.length > 0) {
    // 선택한 행의 QNA_NUMBER 목록 생성
    for (var i = 0; i < selectedRows.length; i++) {
        var rId = selectedRows[i];
        var qnaNumber = gridObj.gridGetCellValueId(rId, 'QNA_NUMBER');
        if (qnaNumber) {
            qnaNumbers.push(qnaNumber);
        }
    }
}

// 선택한 행이 없으면 경고 메시지 표시
if (qnaNumbers.length === 0) {
    Alert("다운로드할 항목을 선택해주세요.");
    return;
}

// 엑셀 다운로드 실행
var params = {"SELECTED_QNA_NUMBERS" : qnaNumbers.join(',')};
var fileId = 'LEGAL_REVIEW_TEMPLATE.xlsx';
sepoaExcelProcessor('down', 'sepoa.svc.board.SepoaQAService', 'doExcelDownload', null, fileId, params);
